exercises.solution:
n = int(input())
if n % 2 == 0:
    print("偶数")
else:
    print("奇数")

score = int(input())
if score >= 90:
    print("优秀")
elif score >= 80:
    print("良好")
elif score >= 60:
    print("及格")
else:
    print("不及格")

n = int(input())
if n < 2:
    print("不是素数")
else:
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            print("不是素数")
            break
    else:
        print("是素数")

s = input()
letters = 0
digits = 0
for ch in s:
    if ('a' <= ch <= 'z') or ('A' <= ch <= 'Z'):
        letters += 1
    elif '0' <= ch <= '9':
        digits += 1
print(f"字母={letters}")
print(f"数字={digits}")

word = input().strip()
counts = {}
for ch in word:
    counts[ch] = counts.get(ch, 0) + 1
for ch, cnt in counts.items():
    print(f"{ch}:{cnt}")
